<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/libs/setup.inc.php';
$actor=alphano_require_login();if(empty(alphano_user()['admin']))alphano_fail('Accesso riservato agli amministratori completi.',403);
$steps=alphano_setup_steps();$step=(string)($_GET['step']??'');if($step!==''&&!isset($steps[$step]))alphano_fail('Passaggio non trovato.',404);
$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 alphano_require_csrf();try{
  $action=$_POST['action']??'save';$target=(string)($_POST['step']??$step);if(!isset($steps[$target]))throw new DomainException('Passaggio non valido.');
  if(in_array($action,['complete','skip','reopen'],true)){
   alphano_setup_mark($target,['complete'=>'completed','skip'=>'skipped','reopen'=>'pending'][$action],$actor);
   $next=$action==='reopen'?$target:alphano_setup_next($target);header('Location: /admin/setup.php'.($next!==''?'?step='.$next:''),true,303);exit;
  }
  alphano_setup_save($target,$_POST,$actor);if($action==='toggle'&&empty($_POST['feature_enabled'])){alphano_setup_mark($target,'completed',$actor);$target=alphano_setup_next($target);}
  header('Location: /admin/setup.php?step='.$target.'&saved=1',true,303);exit;
 }catch(Throwable $e){http_response_code(422);$error=$e instanceof DomainException?$e->getMessage():'Salvataggio non riuscito. Consulta il log PHP.';if(!$e instanceof DomainException)error_log('[Setup] '.$e->getMessage());}
}
$config=require dirname(__DIR__).'/config/app.php';$status=alphano_setup_status();$db=ConnectDB();$areas=$db->query('SELECT * FROM world_areas ORDER BY title');$cities=$db->query('SELECT * FROM city ORDER BY city');$catalog=rpg_catalog();$editing=(int)($_GET['id']??0);$row=[];
if($editing&&in_array($step,['races','ethnicities','cities','organizations','corporations'],true)){
 if($step==='races'){foreach($catalog['races'] as $r)if($r['id']===$editing)$row=$r;}
 else{$table=['ethnicities'=>'etnie','cities'=>'city','organizations'=>'organizzazioni','corporations'=>'corporazioni'][$step];$row=$db->query('SELECT * FROM '.$table.' WHERE id=?',[$editing])[0]??[];}
 if(!$row)alphano_fail('Elemento non trovato.',404);
}
function setup_input(string $name,string $label,mixed $value='',string $type='text',bool $required=false):void {echo '<label>'.alphano_escape($label).'<input name="'.alphano_escape($name).'" type="'.$type.'" value="'.alphano_escape($value).'" '.($required?'required':'').'></label>';}
function setup_check(string $name,string $label,bool $checked=false):void {echo '<label class="check"><input type="checkbox" name="'.alphano_escape($name).'" value="1" '.($checked?'checked':'').'>'.alphano_escape($label).'</label>';}
function setup_text(string $name,string $label,mixed $value=''):void {echo '<label>'.alphano_escape($label).'<textarea name="'.alphano_escape($name).'" rows="4">'.alphano_escape($value).'</textarea></label>';}
function setup_select(string $name,string $label,array $options,mixed $selected=''):void {echo '<label>'.alphano_escape($label).'<select name="'.alphano_escape($name).'">';foreach($options as $v=>$text)echo '<option value="'.alphano_escape($v).'" '.((string)$v===(string)$selected?'selected':'').'>'.alphano_escape($text).'</option>';echo '</select></label>';}
function setup_hidden(string $step,string $action='save'):void {echo '<input type="hidden" name="_csrf" value="'.alphano_escape(alphano_csrf_token()).'"><input type="hidden" name="step" value="'.$step.'"><input type="hidden" name="action" value="'.$action.'">';}
?>
