<ol class="setup-checklist"><?php foreach($steps as $key=>$title):?><li data-status="<?=alphano_escape($status[$key]??'pending')?>"><a href="?step=<?=$key?>" <?=$step===$key?'aria-current="step"':''?>><?=alphano_escape($title)?></a><span><?=['completed'=>'Completato','skipped'=>'Saltato · da riprendere','pending'=>'Da completare'][$status[$key]??'pending']?></span></li><?php endforeach;?></ol>
