<?php elseif($step==='cities'):?><p>Crea le città e scegli separatamente se prevedono elezioni. Puoi collegarle alle destinazioni già create, senza duplicare le chat.</p><p><a href="?step=cities">Nuova città</a></p><ul><?php foreach($cities as $c):?><li><a href="?step=cities&amp;id=<?=(int)$c['id']?>"><?=alphano_escape($c['city'])?></a> · <?=$c['elections_enabled']?'elezioni abilitate':'elezioni disabilitate'?></li><?php endforeach;?></ul><form method="post"><?php setup_hidden($step);?><input type="hidden" name="id" value="<?=$editing?>"><?php setup_input('name','Nome della città',$row['city']??'','text',true);setup_text('description','Descrizione / statuto',$row['statuto']??'');setup_check('elections_enabled','Abilita le elezioni per questa città',!empty($row['elections_enabled']));$linked=$editing?(int)($db->query('SELECT id FROM world_areas WHERE city_id=?',[$editing])[0]['id']??0):0;setup_select('area_id','Card della mappa',[0=>'Crea una nuova card']+array_column($areas,'title','id'),$linked);?><button>Salva città</button></form><p><a href="/admin/cariche.php">Cariche e permessi</a> · <a href="/admin/utenti.php">Assegna cittadinanza e ruoli</a></p>
